
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_acggap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_acggap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.691442201707398e-02, -6.589510518571831e-02, -6.443326970028396e-02, -6.233950995296735e-02, -5.934663552718224e-02, -5.508345916582481e-02, -4.905546131344447e-02, -4.069328847614651e-02, -2.974853777604110e-02, -1.798846097230325e-02, -1.314850830878994e-02, -3.913008511141657e-02, -4.655011566418865e-02, -3.318337529590350e-02, -1.785453217977489e-02, -5.184131715266451e-03, -4.445773204928423e-04, -6.627900814484906e-06, -9.565828691287635e-09, -4.576530847075247e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


